  setTimeout(() => console.log(i), 1); // queued; reads the shared i later
}                                      // loop ends with i = 3

for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 1); // queued; keeps this iteration's own i (0, 1, 2)
}

// both loops done, the timers run in order => 3 3 3, then 0 1 2

